  "sad-time"(p, c, fig) { mount(() => { const q = D.sad.years; lineChart(p, {series: [{name: "Hits, median valence", x: q.years, y: q.hit, color: css("--s1")}, {name: "All tracks, median valence", x: q.years, y: q.all, color: css("--s2")}], xfmt: String, tipfmt: y => f(y, 3), label: "Median valence of hits over time"}); }); dataTable(fig, ["Genre", "Rank correlation with popularity", "q (FDR)"], D.sad.genres.map(r => [r.genre, f(r.rho), r.q])); },
  "country-heat"(p, c, fig) { let per = "2023-2025"; const go = () => { const q = D.geo.periods[per], names = q.order.map(k => q.names[q.countries.indexOf(k)]), keys = q.order.map(k => q.countries.indexOf(k)), V = keys.map(i => q.z[i]), cols = D.geo.features.map(k => NAMES[k]); heat(p, {rows: names, cols, v: V, kind: "div", max: 1.5, minCell: 34, cellH: 19, left: 128, bottom: 86, label: "Country chart profiles relative to the Global chart", tip: (r, k) => `<b>${esc(names[r])}: ${cols[k]}</b><br>${f(V[r][k])} SD from Global<br>value ${f(q.profile[keys[r]][k], 3)}`, scale: "Chart-day-weighted audio profile compared with the Global chart. Red: above Global. Blue: below."}); dataTable(fig, ["Country", ...cols], names.map((n, r) => [n, ...q.profile[keys[r]].map(v => f(v, 3))])); }; seg(c, "Period", [["2023-2025", "2023-2025"], ["2017-2021", "2017-2021"]], per, v => { per = v; go(); }); mount(go); },
  convergence(p, c, fig) { mount(() => { p.innerHTML = ""; const q = D.geo.conv, a = h("div"), b = h("div", {style: "margin-top:18px"}), yr = n => Math.floor(n); p.append(h("div", {class: "lab", style: "font:600 13px var(--ui);margin-bottom:4px"}, "Songs shared by two countries' Top 50"), a, h("div", {style: "font:600 13px var(--ui);margin:16px 0 4px"}, "Distance between countries' sound profiles"), b); lineChart(a, {series: [{name: "All qualifying songs", x: q.x, y: q.j.map(v => v == null ? null : v * 100), lo: q.jl.map(v => v == null ? null : v * 100), hi: q.jh.map(v => v == null ? null : v * 100), color: css("--s1")}, {name: "Fixed core of 25 songs", x: q.x, y: q.c.map(v => v == null ? null : v * 100), color: css("--s2")}], ymin: 0, yfmt: v => v + "%", xfmt: v => Number.isInteger(v) ? v : `${yr(v)} Q${Math.round((v - yr(v)) * 4) + 1}`, xticks: [2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025], tipfmt: y => f(y, 1) + "%", label: "Chart overlap over time"}); lineChart(b, {series: [{name: "Observed", x: q.x, y: q.d, color: css("--s1")}, {name: "If songs were dealt at random", x: q.x, y: q.n, color: css("--s2")}], ymin: 0, xfmt: v => Number.isInteger(v) ? v : `${yr(v)} Q${Math.round((v - yr(v)) * 4) + 1}`, xticks: [2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025], tipfmt: y => f(y, 2), label: "Audio distance between countries"}); p.append(h("div", {class: "legend", style: "margin-top:6px"}, h("span", {}, `${q.size} countries present in every quarter. The break marks 2022, which no source covers.`))); }); dataTable(fig, ["Quarter", "Overlap", "Core 25 overlap", "Audio distance"], D.geo.conv.x.map((x, i) => D.geo.conv.j[i] == null ? null : [D.geo.conv.q[i], pct(D.geo.conv.j[i], 1), pct(D.geo.conv.c[i], 1), f(D.geo.conv.d[i])]).filter(Boolean)); },
  reach(p, c, fig) { const q = D.geo.reach; mount(() => { p.innerHTML = ""; const a = h("div"); p.append(a); const groups = [["1-3 countries", 1, 3], ["4-9 countries", 4, 9], ["10-18 countries", 10, 18], ["19-39 countries", 19, 39], ["40 or more", 40, 999]], total = q.hist.reduce((x, y) => x + y, 0); bars(a, {rows: groups.map(([label, lo, hi]) => ({label, v: [q.hist.reduce((t, n, i) => t + (q.edges[i] >= lo && q.edges[i] <= hi ? n : 0), 0) / total]})), series: ["Share of charting songs"], max: 1, fmt: v => pct(v, 1), tick: v => pct(v), label: "How many countries songs reach"}); const col = (t, l) => h("div", {}, h("h4", {}, t), h("ol", {}, ...l.slice(0, 5).map(x => h("li", {}, `${x.name} / ${x.artist} (${x.countries})`)))); p.append(h("div", {class: "columns"}, col("Most-charted international songs", q.ex.international), col("Regional favourites", q.ex.regional), col("Concentrated in 1-3 countries", q.ex.concentrated))); }); dataTable(fig, ["Feature", "International median", "Concentrated median", "Cliff's δ", "q (FDR)"], q.tests.map(r => [NAMES[r.feature], f(r.a, 3), f(r.b, 3), f(r.d), r.q])); },
