  function card() { const el = $("#x-card"), r = st.sel; if (!r) { el.innerHTML = ""; return; } const bar = k => { const v = r[C[k]], av = median(k); return `<div class="meter"><span>${NAMES[k]}</span><div><i style="width:${v * 100}%"></i><u style="left:${av * 100}%" title="Median of all explorer tracks"></u></div><span>${v.toFixed(2)}</span></div>`; }; const n = r[C.countries]; el.innerHTML = `<h4>${esc(r[C.name])}</h4><p class="sub">${esc(r[C.artist])}${r[C.year] ? " · " + r[C.year] : ""}${r[C.genre] >= 0 ? " · " + esc(T.genres[r[C.genre]]) : ""}<br>Archetype: ${esc(T.archetypes[r[C.archetype]])}</p>${["valence", "energy", "danceability", "acousticness", "speechiness", "instrumentalness", "liveness"].map(bar).join("")}<div class="legend" style="margin:4px 0 0"><span>Dark tick: median of all explorer tracks</span></div><div class="stats"><span><b>${Math.round(r[C.tempo])}</b>BPM</span><span><b>${r[C.loudness].toFixed(1)}</b>dB</span><span><b>${r[C.duration].toFixed(1)}</b>minutes</span><span><b>${r[C.top50_days].toLocaleString()}</b>country Top 50 days</span><span><b>${r[C.best_rank] ?? "n/a"}</b>best Spotify rank</span><span><b>${r[C.hot100_peak] ?? "n/a"}</b>Hot 100 peak</span><span><b>${r[C.hot100_weeks] ?? "n/a"}</b>Hot 100 weeks</span><span><b>${r[C.global_streams] ? (r[C.global_streams] / 1e6).toFixed(0) + "M" : "n/a"}</b>Global streams, 2017-21</span></div><p class="sub">${n.length ? `Charted in ${n.length} ${n.length === 1 ? "country" : "countries"}: ${n.slice(0, 14).map(i => esc(T.country_names[i])).join(", ")}${n.length > 14 ? "…" : ""}` : "No country Top 50 record in these datasets."}</p><a href="https://open.spotify.com/track/${esc(r[C.id])}" target="_blank" rel="noopener">Open on Spotify</a>`; }
